import {
    flushPromisesWithFakeTimers,
    getMockClientWithEventEmitter,
    mkPusher,
    mockClientMethodsUser,
    mockPlatformPeg,
} from '../../../../../test-utils';
import Modal from '../../../../../../src/Modal';
import LogoutDialog from '../../../../../../src/components/views/dialogs/LogoutDialog';
import {
